import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  // expectStatus returns the parsed body; a 204 has none, so the result is null.
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "logout sets a session cookie header").toBeDefined();
  expect(cookie?.value, "session cookie value is emptied").toMatch(/^session=(""|;|$)/);
  expect(cookie?.value.toLowerCase(), "session cookie is expired").toMatch(/max-age=0|expires=thu, 01 jan 1970/);
});
